import pandas as pd
import numpy as np

# Load the Transport data and the list of neighboring boroughs into pandas DataFrames
transport_data = pd.read_csv('getisord_2022_transport.csv')
adjacency_data = pd.read_csv('borough_adjacency.csv')

# Handle missing values in the Transport data by dropping rows with missing values
transport_data = transport_data.dropna()

# Calculate the total Transport value for each borough and its neighbors by summing the Transport values for each borough and its neighbors
neighborhoods = {}
for index, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighborhoods:
        neighborhoods[borough] = []
    neighborhoods[borough].append(neighbor)
    if neighbor not in neighborhoods:
        neighborhoods[neighbor] = []
    neighborhoods[neighbor].append(borough)

neighborhoods = {borough: set(neighbors) for borough, neighbors in neighborhoods.items()}

transport_values = {}
for index, row in transport_data.iterrows():
    borough = row['borough']
    transport_values[borough] = row['Transport_value']
    for neighbor in neighborhoods[borough]:
        if neighbor in transport_values:
            transport_values[neighbor] += row['Transport_value']

# Calculate the citywide average of the total Transport values
citywide_average = np.mean(list(transport_values.values()))

# Use the Getis-Ord Gi* method to calculate the z-score for each borough, considering its total Transport value and the citywide average
gi_values = {}
for borough, total_transport in transport_values.items():
    if np.isnan(total_transport):
        continue
    gi_value = (total_transport - citywide_average) / np.std(list(transport_values.values()))
    gi_values[borough] = gi_value

# Identify boroughs with a z-score greater than 1.96 (95% confidence) or 2.576 (99% confidence) as hot spots, and those with a z-score less than -1.96 or -2.576 as cold spots
hot_spots = {borough: gi_value for borough, gi_value in gi_values.items() if np.abs(gi_value) > 1.96}
cold_spots = {borough: gi_value for borough, gi_value in gi_values.items() if np.abs(gi_value) > 2.576 and gi_value < 0}

# Print the list of boroughs that are statistically significant hot or cold spots, along with their Gi* values and the computed z-score
results = []
for borough, gi_value in hot_spots.items():
    results.append(f'{borough} (HOT, Gi*={gi_value}, gi_value={gi_value})')
for borough, gi_value in cold_spots.items():
    results.append(f'{borough} (COLD, Gi*={gi_value}, gi_value={gi_value})')

# Print the number of data points used in the analysis
data_points_used = len(transport_data)

# Print the results
print(f'data_points_used = {data_points_used}')
print(f'FINAL ANSWER: {", ".join(results)}')

import pandas as pd
import numpy as np

# Load the Transport data and the list of neighboring boroughs into pandas DataFrames
transport_data = pd.read_csv('getisord_2022_transport.csv')
adjacency_data = pd.read_csv('borough_adjacency.csv')

# Handle missing values in the Transport data by dropping rows with missing values
transport_data = transport_data.dropna()

# Calculate the total Transport value for each borough and its neighbors by summing the Transport values for each borough and its neighbors
neighborhoods = {}
for index, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighborhoods:
        neighborhoods[borough] = []
    neighborhoods[borough].append(neighbor)
    if neighbor not in neighborhoods:
        neighborhoods[neighbor] = []
    neighborhoods[neighbor].append(borough)

neighborhood_values = {}
for borough, neighbors in neighborhoods.items():
    neighborhood_values[borough] = transport_data.loc[transport_data['borough'].isin(neighbors), 'Transport_value'].sum()

# Calculate the citywide average of the total Transport values
citywide_average = transport_data['Transport_value'].mean()

# Use the Getis-Ord Gi* method to calculate the z-score for each borough, considering its total Transport value and the citywide average
gi_values = {}
for borough, neighborhood_value in neighborhood_values.items():
    gi_value = (neighborhood_value - citywide_average) / np.sqrt(citywide_average * (1 - (neighborhood_value / transport_data['Transport_value'].sum())))
    gi_values[borough] = gi_value

# Identify boroughs with a z-score greater than 1.96 (95% confidence) or 2.576 (99% confidence) as hot spots, and those with a z-score less than -1.96 or -2.576 as cold spots
hot_spots = {borough: gi_value for borough, gi_value in gi_values.items() if gi_value > 1.96}
cold_spots = {borough: gi_value for borough, gi_value in gi_values.items() if gi_value < -1.96}

# Print the list of boroughs that are statistically significant hot or cold spots, along with their Gi* values and the computed z-score
results = []
for borough, gi_value in hot_spots.items():
    results.append(f"{borough} (HOT, Gi*={gi_value}, gi_value={gi_value})")
for borough, gi_value in cold_spots.items():
    results.append(f"{borough} (COLD, Gi*={gi_value}, gi_value={gi_value})")

print(f"FINAL ANSWER: {', '.join(results)}")
print(f"data_points_used = {len(transport_data)}")
